                        mediaHtml += `<div class="media-placeholder image-grid">`;
                        for (const imgDesc of allImages) {
                            mediaHtml += `<div class="img-placeholder">${imgDesc}</div>`;
                        }
                        mediaHtml += `</div>`;
                    }
                }

                // 提取统计数据 (逻辑不变)
                const statsMatch = /\[STATS\|COMMENTS=([^|]+)\|RETWEETS=([^|]+)\|LIKES=([^\]]+)\]/.exec(innerContent);
                let statsHtml = '';
                if (statsMatch) {
                    statsHtml = `<div class="tweet-stats"><div class="stat-item"><span>💬</span><span>${statsMatch[1]}</span></div><div class="stat-item"><span>🔁</span><span>${statsMatch[2]}</span></div><div class="stat-item"><span>❤️</span><span>${statsMatch[3]}</span></div><div class="stat-item"><span>🔗</span></div></div>`;
                }

                return `
                    <div class="tweet-item">
                        <div class="tweet-avatar">${avatar}</div>
                        <div class="tweet-body">
                            <div class="author-info">
                                <span class="tweet-author-name">${name}</span>
                                <span class="tweet-author-handle">${handle}</span>
                                <span class="tweet-time">· ${time}</span>
                                ${visibilityIcon}
                            </div>
                            <div class="tweet-content">${content}</div>
                            ${mediaHtml}
                            ${statsHtml}
                        </div>
                    </div>`;
            }
            // --- 核心修正区域 结束 ---

            function renderAll() {
                const headerData = `$1`;
                const pinnedTweetData = `$2`;
                const tweetsData = `$3`;
                let finalHtml = '';

                const headerRegex = /\[PROFILE_HEADER\|COVER_DESC=([^|]+)\|AVATAR=([^|]+)\|NAME=([^|]+)\|HANDLE=([^|]+)\|BIO=([^\]]+)\]\s*\[JOIN_DATE=([^\]]+)\]\s*\[FOLLOW_STATS\|FOLLOWING=([^|]+)\|FOLLOWERS=([^\]]+)\]/;
                const headerMatch = headerRegex.exec(headerData);
                if (headerMatch) {
                    finalHtml += `
                        <div class="profile-header">
                            <div class="cover-photo">${headerMatch[1]}</div>
                            <div class="profile-details">
                                <div class="avatar-section">
                                    <div class="profile-avatar">${headerMatch[2]}</div>
                                    <div class="follow-button">Follow</div>
                                </div>
                                <div class="author-name">${headerMatch[3]}</div>
                                <div class="author-handle">${headerMatch[4]}</div>
                                <div class="bio">${headerMatch[5]}</div>
                                <div class="join-date">📅 ${headerMatch[6]}</div>
                                <div class="follow-stats"><span>${headerMatch[7]}</span> Following &nbsp;&nbsp; <span>${headerMatch[8]}</span> Followers</div>
                            </div>
                        </div>`;
                }

                if (pinnedTweetData) {
                    const cleanPinnedData = pinnedTweetData.replace(/\[\/?PINNED_TWEET\]/g, '').trim();
                    finalHtml += `<div class="pinned-tweet-section">📌 Pinned</div>`;
                    finalHtml += renderTweet(cleanPinnedData);
                }

                const tweetRegex = /\[TWEET[\s\S]*?\[\/TWEET\]/g;
                let tweetMatch;
                while ((tweetMatch = tweetRegex.exec(tweetsData)) !== null) {
                    finalHtml += renderTweet(tweetMatch[0]);
                }

                return finalHtml;
            }
        })();
    </script>
</body>
</html>
