        </div>
        <div class="book-list-container" id="book-list"></div>
        <div class="fanqie-nav">
            <!-- --- 核心修改区域: 为导航项添加onclick事件 --- -->
            <div class="nav-item ${'$2' === '首页' ? 'active' : ''}" onclick="sendCommand('黄茄小说刷新，清除搜索过的关键词')"><span class="icon">🏠</span>首页</div>
            <div class="nav-item ${'$2' === '刷新' ? 'active' : ''}" onclick="sendCommand('黄茄小说刷新，保留搜索过的关键词')"><span class="icon">🔄</span>刷新</div>
            <div class="nav-item ${'$2' === '搜索' ? 'active' : ''}" onclick="sendCommand('黄茄小说搜索关键词：')"><span class="icon">🔍</span>搜索</div>
        </div>
    </div>
    <script>
        // --- 核心修改区域 开始: 全局函数定义 ---
        function sendCommand(text) {
            if (typeof triggerSlash === 'function') {
                triggerSlash(`/setinput ${text}`);
            } else {
                console.error("triggerSlash not defined. Cannot send command:", text);
            }
        }

        function handleBookClick(title, author) {
            const commandText = `阅读【${author}】写的小说【${title}】`;
            sendCommand(commandText);
        }
        // --- 核心修改区域 结束 ---

        (function() {
            const bookData = `$1`;
            const container = document.getElementById('book-list');
            if (!container) return;

            const bookRegex = /\[BOOK_ITEM\|COVER_DESC=([^|]+)\|TITLE=([^|]+)\|AUTHOR=([^|]+)\|TAGS=([^\]]+)\]\s*\[SYNOPSIS\]([\s\S]*?)\[\/SYNOPSIS\]\s*\[\/BOOK_ITEM\]/g;
            let match;
            let allBooksHtml = '';

            while ((match = bookRegex.exec(bookData)) !== null) {
                const [_, cover, title, author, tags, synopsis] = match;

                // 对标题和作者进行转义，防止破坏onclick属性
                const sanitizedTitle = title.replace(/'/g, "\\'");
                const sanitizedAuthor = author.replace(/'/g, "\\'");

                const tagsHtml = tags.split(',').map(tag => `<div class="book-tag">${tag.trim()}</div>`).join('');

                // --- 核心修改区域: 为书本项添加onclick事件 ---
                allBooksHtml += `
                    <div class="book-item" onclick="handleBookClick('${sanitizedTitle}', '${sanitizedAuthor}')">
                        <div class="book-cover">${cover}</div>
                        <div class="book-info">
                            <div>
                                <div class="book-title">${title}</div>
                                <div class="book-synopsis">${synopsis.trim()}</div>
                            </div>
                            <div class="book-meta">
                                <div class="book-author">✒️ ${author}</div>
                                <div class="book-tags-container">${tagsHtml}</div>
                            </div>
                        </div>
                    </div>`;
            }
            container.innerHTML = allBooksHtml;
        })();
    </script>
</body>
