    <script>

        const chatNameToUidMap = {
            "冬月梅咲": "0", "梅咲": "0", "咲咲": "0", "学生会长": "0", "一介书生": "0", "@Yuki-shita-Ume": "0",
            "向晚雅": "1", "阿雅": "1", "小雅": "1", "小雅不吃香菜OwO": "1", "今天也想玩吖": "1", "@xiangwanyaOwO": "1",
            "白鸟汐": "2", "小汐": "2", "图书委员": "2", "汐酱今天也很困呢": "2", "无名的观测记录": "2", "@xi^^xi": "2",
            "老司机🚀(21)": "3", "老司机🚀(22)": "3", "老司机🚀(23)": "3", "老司机🚀(24)": "3", "老司机🚀(25)": "3",
        };

        const chatPartnerName = `$1`;
        const messagesData = `$2`;

        // --- 核心修改区域 开始 ---

        /**
         * 【JavaScript 新增】处理快捷输入按钮的点击事件
         */
        function handleQuickInput() {
            // 确保 triggerSlash 函数存在
            if (typeof triggerSlash === 'function') {
                // 构建要填充到主输入框的文本
                const commandText = `向【${chatPartnerName}】发送消息：`;
                // 使用 /setinput 指令来设置主输入框内容
                triggerSlash(`/setinput ${commandText}`);
            } else {
                console.error("triggerSlash not defined.");
                // 如果函数不存在，可以用通知功能提醒用户
                showNotification("错误：快捷输入功能当前不可用。", false);
            }
        }

        // --- 核心修改区域 结束 ---

        async function saveDataToWorldbook(uid, worldbookFile, dataObject) {
            try {
                const contentJson = JSON.stringify(dataObject).replace(/\|/g, '\\|').replace(/"/g, '\\"').replace(/'/g, "\\'");
                const command = `/setentryfield file="${worldbookFile}" uid="${uid}" field=content "${contentJson}"`;
                if (typeof triggerSlash === 'function') {
                    await triggerSlash(command);
                    showNotification(`成功保存到世界书条目：${getUserNameByUid(uid)}(UID: ${uid})！`, true);
                    return true;
                }
            } catch (error) {
                console.error("保存数据到世界书失败:", error);
                return false;
