        async function handleSaveChat() {
            const worldbookFileName = "芋芋头子的安卓手机";
            const currentChatPartner = chatPartnerName;
            const targetUid = chatNameToUidMap[currentChatPartner];

            if (targetUid === undefined) {
                showNotification(`未在UID映射表中找到'${currentChatPartner}'的配置，请检查世界书中对应条目的UID在chatNameToUidMap中是否对应存在。`, false);
                return;
            }
            const msgRegex = /\[MSG\|TYPE=([^|]+)\|AVATAR=([^\]]+)\](.*?)\[\/MSG\]/gs;
            let match;
            const messagesArray = [];
            while ((match = msgRegex.exec(messagesData)) !== null) {
                messagesArray.push({ type: match[1], avatar: match[2], content: match[3].trim() });
            }
            const dataToSave = { characterName: currentChatPartner, messages: messagesArray, saveTime: new Date().toLocaleString() };
            await saveDataToWorldbook(targetUid, worldbookFileName, dataToSave);
        }

        (function () {
            const msgRegex = /\[MSG\|TYPE=([^|]+)\|AVATAR=([^\]]+)\](.*?)\[\/MSG\]/gs;
            let allMessagesHtml = '';
            let match;
            while ((match = msgRegex.exec(messagesData)) !== null) {
                const type = match[1];
                const avatar = match[2];
                const rawContent = match[3].trim();
                let bubbleHtml;

                if (rawContent.startsWith('[CALL_STATUS]')) {
                    const statusText = rawContent.replace(/\[\/?CALL_STATUS\]/g, '').trim();
                    bubbleHtml = `<div class="call-status-message">${statusText}</div>`;
                } else if (rawContent.startsWith('[RECALLED]')) {
                    const recalledText = rawContent.replace(/\[\/?RECALLED\]/g, '').trim();
                    bubbleHtml = `<div class="recalled-message">${recalledText}</div>`;
                } else {
                    let contentHtml;
                    let contentClass = 'content';
                    let innerContent = rawContent;

                    if (rawContent.startsWith('[VIDEO]')) {
                        contentClass += ' content-video';
                        innerContent = rawContent.replace(/\[\/?VIDEO\]/g, '').trim();
                        contentHtml = `<div class="${contentClass}" style="padding-top: 30px;">${innerContent}</div>`;
                    } else if (rawContent.startsWith('[IMAGE]')) {
                        contentClass += ' content-image';
                        innerContent = rawContent.replace(/\[\/?IMAGE\]/g, '').trim();
                        contentHtml = `<div class="${contentClass}">${innerContent}</div>`;
                    } else if (rawContent.startsWith('[VOICE_CALL]')) {
                        contentClass += ' content-voice-call';
                        innerContent = rawContent.replace(/\[\/?VOICE_CALL\]/g, '').trim();
                        contentHtml = `<div class="${contentClass}">${innerContent}</div>`;
                    } else if (rawContent.startsWith('[VIDEO_CALL]')) {
                        contentClass += ' content-video-call';
                        innerContent = rawContent.replace(/\[\/?VIDEO_CALL\]/g, '').trim();
                        contentHtml = `<div class="${contentClass}">${innerContent}</div>`;
                    } else {
                        contentHtml = `<div class="${contentClass}">${innerContent}</div>`;
                    }

                    bubbleHtml = `<div class="message-bubble ${type}"><div class="avatar">${avatar}</div>${contentHtml}</div>`;
                }
                allMessagesHtml += bubbleHtml;
            }
            const container = document.getElementById('message-container');
            if (container) {
                container.innerHTML = allMessagesHtml;
                container.scrollTop = container.scrollHeight;
            }
        })();

        function showNotification(message, isSuccess = false) {
            const notification = document.createElement('div');
            const baseStyle = `
                position: fixed; top: 20px; left: 50%; transform: translateX(-50%);
                color: white; padding: 12px 20px; border-radius: 4px; z-index: 9999;
                box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2); transition: opacity 0.3s ease;`;
            const bgColor = isSuccess ? '#4CAF50' : '#ff4444';
            notification.style.cssText = baseStyle + `background-color: ${bgColor};`;
            notification.textContent = message;
            document.querySelectorAll('.notification').forEach(el => el.remove());
            document.body.appendChild(notification);
            setTimeout(() => {
                notification.style.opacity = '0';
                setTimeout(() => notification.remove(), 300);
            }, 3000);
        }

        function getUserNameByUid(uid) {
            for (const name in chatNameToUidMap) {
                if (chatNameToUidMap[name] === uid) return name;
            }
            return null;
        }
    </script>

</body>

</html>
