    <div class="moments-container" id="moments-container">
        <div class="moments-header">
            <div class="header-info">
                <span class="header-name">$2</span>
                <div class="header-avatar">$1</div>
            </div>
        </div>
        <div class="post-list" id="post-list-container">
        </div>
    </div>

    <script>
        (function () {
            const postsData = `$3`;
            const postListContainer = document.getElementById('post-list-container');
            if (!postListContainer) return;
            const postRegex = /\[POST\|AUTHOR=([^|]+)\|AVATAR=([^|]+)\|TIME=([^\]]+)\]\s*([\s\S]*?)\[\/POST\]/g;
            let postMatch;
            let allPostsHtml = '';

            while ((postMatch = postRegex.exec(postsData)) !== null) {
                const author = postMatch[1];
                const avatar = postMatch[2];
                const time = postMatch[3];
                const innerContent = postMatch[4];
                const contentMatch = /\[CONTENT\]([\s\S]*?)\[\/CONTENT\]/.exec(innerContent);
                const content = contentMatch ? contentMatch[1].trim() : '';

                let mediaHtml = ''; // 用于存放图片或视频的HTML

                // 【升级逻辑】优先检查视频，再检查图片
                const videoRegex = /\[VIDEO\]([\s\S]*?)\[\/VIDEO\]/g;
                let videoMatch;
                const allVideos = [];
                while ((videoMatch = videoRegex.exec(innerContent)) !== null) {
                    allVideos.push(videoMatch[1].trim());
                }

                if (allVideos.length > 0) {
                    // 渲染视频
                    mediaHtml = `<div class="post-videos grid-1">`; // 朋友圈通常只显示一个视频
                    mediaHtml += `<div class="video-placeholder">${allVideos[0]}</div>`;
                    mediaHtml += `</div>`;
                } else {
                    // 如果没有视频，再渲染图片
                    const imageRegex = /\[IMAGE\]([\s\S]*?)\[\/IMAGE\]/g;
                    let imageMatch;
                    const allImages = [];
                    while ((imageMatch = imageRegex.exec(innerContent)) !== null) {
                        allImages.push(imageMatch[1].trim());
                    }
                    if (allImages.length > 0) {
                        const gridClass = allImages.length === 1 ? 'grid-1' : (allImages.length <= 4 ? 'grid-4' : 'grid-9');
                        mediaHtml = `<div class="post-images ${gridClass}">`;
                        for (const imgDesc of allImages) {
                            mediaHtml += `<div class="img-placeholder">${imgDesc}</div>`;
                        }
                        mediaHtml += `</div>`;
                    }
                }

                const likesMatch = /\[LIKES\|USERS=([^\]]+)\]/.exec(innerContent);
                const likesHtml = likesMatch ? `<div class="likes">${likesMatch[1]}</div>` : '';
                const commentRegex = /\[COMMENT\|USER=([^\]]+)\]([\s\S]*?)\[\/COMMENT\]/g;
                let commentsHtml = '';
                let commentMatch;
                let hasComments = false;
                while ((commentMatch = commentRegex.exec(innerContent)) !== null) {
                    hasComments = true;
                    let user = commentMatch[1];
                    let text = commentMatch[2].trim();
                    if (text.startsWith('回复 @')) {
                        const replyUser = text.match(/回复 @([^:]+):/)[1];
                        const replyText = text.replace(/回复 @[^:]+:/, '').trim();
                        commentsHtml += `<div class="comment"><span class="comment-user">${user}</span> 回复 <span class="comment-reply">${replyUser}</span>: ${replyText}</div>`;
                    } else {
                        commentsHtml += `<div class="comment"><span class="comment-user">${user}</span>: ${text}</div>`;
                    }
                }
                const commentsContainer = hasComments ? `<div class="comments">${commentsHtml}</div>` : '';
                const interactionsHtml = (likesHtml || commentsContainer) ? `<div class="interactions-block">${likesHtml}${commentsContainer}</div>` : '';

                allPostsHtml += `
                    <div class="post-item">
                        <div class="post-avatar">${avatar}</div>
                        <div class="post-body">
                            <div class="post-author">${author}</div>
                            <div class="post-content">${content}</div>
                            ${mediaHtml}
                            <div class="post-time">${time}</div>
                            ${interactionsHtml}
                        </div>
                    </div>
                `;
            }

            postListContainer.innerHTML = allPostsHtml;
            document.getElementById('moments-container').scrollTop = 0;
        })();
    </script>

</body>

