                function handleTweetClick(authorName, content) {
                        // 截取前7个字符
                        let truncatedContent = content.substring(0, 7);
                        // 如果原文长度超过7，则加上省略号
                        if (content.length > 7) {
                                truncatedContent += '...';
                        }
