    <div class="twitter-container">
        <div class="detail-header"><span class="back-arrow">←</span><span class="header-title">Post</span></div>
        <div class="scroll-container" id="scroll-container"></div>
    </div>
    <script>
        function renderMainTweet(data) {
            const mainRegex = /\[MAIN_TWEET\|AUTHOR_NAME=([^|]+)\|AUTHOR_HANDLE=([^|]+)\|AVATAR=([^\]]+)\]([\s\S]*?)\[FULL_TIMESTAMP=([^\]]+)\]([\s\S]*?)\[\/MAIN_TWEET\]/;
            const match = mainRegex.exec(data);
            if (!match) return '';
            const [_, name, handle, avatar, innerContent, timestamp, statsContent] = match;

            const contentMatch = /\[CONTENT\]([\s\S]*?)\[\/CONTENT\]/.exec(innerContent);
            const content = contentMatch ? contentMatch[1].trim() : '';

            let mediaHtml = '';
            const videoMatch = /\[VIDEO\]([\s\S]*?)\[\/VIDEO\]/.exec(innerContent);
            if (videoMatch) {
                mediaHtml = `<div class="media-placeholder"><div class="video-placeholder">${videoMatch[1].trim()}</div></div>`;
            } else {
                const imageMatch = /\[IMAGE\]([\s\S]*?)\[\/IMAGE\]/.exec(innerContent);
                if(imageMatch) mediaHtml = `<div class="media-placeholder"><div class="img-placeholder">${imageMatch[1].trim()}</div></div>`;
            }

            const statsRegex = /\[DETAILED_STATS\|RETWEETS=([^|]+)\|LIKES=([^|]+)\|BOOKMARKS=([^\]]+)\]/;
            const statsMatch = statsRegex.exec(statsContent);
            let statsHtml = '';
            if (statsMatch) {
                statsHtml = `
                    <div class="detailed-stats-container">
                        <div><span>${statsMatch[1]}</span> Retweets</div>
                        <div><span>${statsMatch[2]}</span> Likes</div>
                        <div><span>${statsMatch[3]}</span> Bookmarks</div>
                    </div>`;
            }

            return `
                <div class="main-tweet-wrapper">
                    <div class="main-author-info">
                        <div class="main-avatar">${avatar}</div>
                        <div class="main-author-names">
                            <div class="main-author-name">${name}</div>
                            <div class="main-author-handle">${handle}</div>
                        </div>
                    </div>
                    <div class="main-tweet-content">${content}</div>
                    ${mediaHtml}
                    <div class="full-timestamp">${timestamp}</div>
                    ${statsHtml}
                    <div class="action-bar"><span>💬</span><span>🔁</span><span>❤️</span><span>🔗</span></div>
                </div>
                <div class="replies-header">Replies</div>
            `;
        }

        function renderReply(data) {
            const replyRegex = /\[REPLY_TWEET\|AUTHOR_NAME=([^|]+)\|AUTHOR_HANDLE=([^|]+)\|AVATAR=([^|]+)\|TIME=([^\]]+)\]([\s\S]*?)\[\/REPLY_TWEET\]/;
            const match = replyRegex.exec(data);
            if (!match) return '';
            const [_, name, handle, avatar, time, innerContent] = match;

            const contentMatch = /\[CONTENT\]([\s\S]*?)\[\/CONTENT\]/.exec(innerContent);
            const content = contentMatch ? contentMatch[1].trim() : '';

            const statsMatch = /\[STATS\|COMMENTS=([^|]+)\|RETWEETS=([^|]+)\|LIKES=([^\]]+)\]/.exec(innerContent);
            let statsHtml = '';
            if (statsMatch) {
                statsHtml = `
                    <div class="reply-stats">
                        <div>💬<span>${statsMatch[1]}</span></div>
                        <div>🔁<span>${statsMatch[2]}</span></div>
                        <div>❤️<span>${statsMatch[3]}</span></div>
                    </div>`;
            }

            return `
                <div class="reply-item">
                    <div class="reply-avatar">${avatar}</div>
                    <div class="reply-body">
                        <div class="reply-author-info">
                            <span class="reply-author-name">${name}</span>
                            <span class="reply-author-handle">${handle}</span>
                            <span class="reply-time">· ${time}</span>
                        </div>
                        <div class="reply-content">${content}</div>
                        ${statsHtml}
                    </div>
                </div>`;
        }

        (function () {
            const mainTweetData = `$1`;
            const repliesData = `$2`;
            const container = document.getElementById('scroll-container');
            if (!container) return;

            let finalHtml = renderMainTweet(mainTweetData);

            const replyRegex = /\[REPLY_TWEET[\s\S]*?\[\/REPLY_TWEET\]/g;
            let replyMatch;
            while ((replyMatch = replyRegex.exec(repliesData)) !== null) {
                finalHtml += renderReply(replyMatch[0]);
            }

            container.innerHTML = finalHtml;
        })();
    </script>
</body>
</html>
