<body>
    <div class="fanqie-reader-container theme-parchment" id="reader-container">
        <div class="reader-header">
            <span class="back-arrow" id="back-btn">‹</span>
            <span class="book-title-header" id="book-title"></span>
        </div>
        <div class="content-container" id="novel-content"></div>
        <div class="reader-footer">
            <div class="footer-icon" id="home-btn"><span class="icon">🏠</span>首页</div>
            <button class="footer-button" id="continue-btn"></button>
            <div class="footer-icon" id="settings-btn"><span class="icon">⚙️</span>设置</div>
        </div>
    </div>

    <div id="theme-modal">
        <div class="theme-selector">
            <div class="theme-option" data-theme="parchment"><div class="theme-swatch" style="background: #fdf6e3;"></div><span class="theme-name">经典护眼</span></div>
            <div class="theme-option" data-theme="night"><div class="theme-swatch" style="background: #121212;"></div><span class="theme-name">夜间深黑</span></div>
            <div class="theme-option" data-theme="paper"><div class="theme-swatch" style="background: #ffffff;"></div><span class="theme-name">静谧雅白</span></div>
            <div class="theme-option" data-theme="mint"><div class="theme-swatch" style="background: #e6f3e6;"></div><span class="theme-name">清新豆绿</span></div>
            <div class="theme-option" data-theme="sepia"><div class="theme-swatch" style="background: #fbf0d9;"></div><span class="theme-name">温暖复古</span></div>
            <div class="theme-option" data-theme="slate"><div class="theme-swatch" style="background: #dde5ed;"></div><span class="theme-name">简约灰蓝</span></div>
        </div>
    </div>

    <script>
        // --- 通用指令发送函数 ---
        function sendCommand(text) {
            if (typeof triggerSlash === 'function') {
                triggerSlash(`/setinput ${text}`);
            } else {
                console.error("triggerSlash not defined. Cannot send command:", text);
            }
        }

        // --- 渲染初始内容 ---
        (function() {
            const headerData = `$1`;
            const contentData = `$2`;
            const footerData = `$3`;
            const headerMatch = /\[BOOK_HEADER\|TITLE=([^|]+)\|AUTHOR=([^\]]+)\]/.exec(headerData);
            if(headerMatch) document.getElementById('book-title').textContent = headerMatch[1];
            const contentMatch = /\[CONTENT_BODY\]([\s\S]*?)\[\/CONTENT_BODY\]/.exec(contentData);
            if(contentMatch) {
                const rawText = contentMatch[1].trim();
                const paragraphs = rawText.split(/\n+/).map(p => `<p>${p.trim()}</p>`).join('');
                document.getElementById('novel-content').innerHTML = paragraphs;
            }
            const footerMatch = /\[READER_FOOTER\|PLACEHOLDER=([^\]]+)\]/.exec(footerData);
            if(footerMatch) document.getElementById('continue-btn').textContent = footerMatch[1];
        })();

        // --- 交互逻辑绑定 ---
        const homeBtn = document.getElementById('home-btn');
        const continueBtn = document.getElementById('continue-btn');
        const backBtn = document.getElementById('back-btn');
        const bookTitleElem = document.getElementById('book-title');

        // [新增] 返回首页/返回上一页 按钮
        homeBtn.addEventListener('click', () => sendCommand('回到黄茄小说首页'));
        backBtn.addEventListener('click', () => sendCommand('回到黄茄小说首页')); // 左上角返回也视为返回首页

        // [新增] 继续阅读按钮
        continueBtn.addEventListener('click', () => {
            const bookTitle = bookTitleElem.textContent.trim();
            if (bookTitle) sendCommand(`继续阅读【${bookTitle}】`);
        });

        // --- 主题切换逻辑 (保留) ---
        const settingsBtn = document.getElementById('settings-btn');
        const themeModal = document.getElementById('theme-modal');
        const themeOptions = document.querySelectorAll('.theme-option');
        const readerContainer = document.getElementById('reader-container');
        settingsBtn.addEventListener('click', () => { themeModal.style.display = 'flex'; });
        themeModal.addEventListener('click', (e) => { if (e.target === themeModal) themeModal.style.display = 'none'; });
        themeOptions.forEach(option => {
            option.addEventListener('click', () => {
                const selectedTheme = option.dataset.theme;
                readerContainer.className = 'fanqie-reader-container';
                readerContainer.classList.add(`theme-${selectedTheme}`);
                themeModal.style.display = 'none';
            });
        });
    </script>
</body>
</html>
